import json;d=json.load(open('/private/tmp/claude-501/-Users-arijit-Coding-Python-DataQ/5ffbb754-c47f-4bef-b45f-a36850170a48/scratchpad/issues.json'));p=json.load(open('/private/tmp/claude-501/-Users-arijit-Coding-Python-DataQ/5ffbb754-c47f-4bef-b45f-a36850170a48/scratchpad/prs.json'))
print(len(d),len(p), sum(len(x['body'] or '') for x in d))
for x in d: print(x['number'],len(x['body'] or ''),x['title'][:90])
for x in p: print('PR',x['number'],len(x['body'] or ''),x['title'][:90])"

